75	function view(record: ResearchCycle) {
76	  const { owner: _owner, ...visible } = record;
77	  const planningStatus = createResearchPlanner(record.plan).getStatus();
78	  let accounting: Record<string, unknown>;
79	  try {
80	    accounting = summarizeAccounting(record.grants, record.ledger, { cycleId: record.id, projectId: record.projectId });
81	  } catch (error) {
82	    accounting = {
83	      ledgerHealthy: false,
84	      assessmentOnly: true,
85	      billingVerified: false,
86	      reason: "UNKNOWN_LIABILITY",
87	      error: error instanceof Error ? error.message : String(error),
88	    };
89	  }
90	  const facts = retryAttemptFacts(record.attempts, record.ledger, { cycleId: record.id, projectId: record.projectId });
91	  const completedIds = facts.filter((fact) => fact.state === "completed").map((fact) => fact.id);
92	  const duplicateSuccess = completedIds.length > 1;
93	  const nextSafeAction =
94	    record.status === "completed" || completedIds.length
95	      ? `${duplicateSuccess ? "Review all duplicate successes and their separate costs. " : ""}Completion blocks further submissions; findings do not satisfy criteria automatically. Inspect the same saved attempt to recover failed local output processing.`
96	      : facts.some((fact) => fact.state === "live")
97	        ? "Existing local research remains live. Inspect the same saved Agent attempt; do not retry or replace live work."
98	        : facts.some((fact) => fact.state === "unclassified")
99	          ? "Legacy attempt has no frozen recovery contract. Inspect its original history manually; never submit automatic replacement research."
100	          : facts.some((fact) => fact.state === "unknown")
101	            ? "Preserve unknown original work and liabilities. No saved remote ID means the original remains unknown. Recover saved remote IDs with researchMode=recover. Any explicit researchMode=replace needs operator approve-replacement for EVERY unknown original, new exact-request funding and total exposure approval. No automatic replacement."
102	            : facts.length
103	              ? "Confirmed failure or proven nondispatch is retained. Revise and preview the draft; explicit researchMode=retry requires new exact-request funding and current total exposure approval. No automatic resubmission."
104	              : "Update the plan and preview the compiled request. Only operator grants and fresh request assessments can authorize spending.";
105	  const completionSummary = { remoteCompletedAttemptIds: completedIds, duplicateSuccess };
106	  const finalReport =
107	    record.status === "completed"
108	      ? {
109	          cycleId: record.id,
110	          status: record.status,
111	          completionSummary,
112	          recordedCriteria: planningStatus.criteria,
113	          criteriaRequiringReview: planningStatus.criteria.filter(
114	            (criterion) =>
115	              (criterion.status !== "supported" && criterion.status !== "excluded") ||
116	              criterion.evidenceIssues.length > 0,
117	          ),
118	          recordedGaps: record.plan.gaps,
119	          assumptions: record.plan.assumptions,
120	          automaticCriterionSatisfaction: false,
121	          usage: accounting,
122	          nextSafeAction,
123	          furtherResearchRequiresNewCycleAndOperatorPermission: true,
124	        }
125	      : undefined;
126	  return {
127	    ...visible,
128	    ...planningStatus,
129	    accounting,
130	    nextSafeAction,
131	    completionSummary,
132	    ...(finalReport ? { finalReport } : {}),
133	  };
134	}
