export type MockRunStatus = "queued" | "running" | "completed" | "failed" | "cancelled";

export interface MockRun {
  id: string;
  status: MockRunStatus;
  stopReason?: "schema_satisfied" | "budget_reached" | "time_limit_reached" | "stopped" | "error" | "cancelled";
