  createGuidedPrototype,
  type GuidedPrototype,
  type MonitorBounds,
  type PrototypeStore,
} from "./fixtures/guided-prototype/prototype.js";

const FAST_BOUNDS: MonitorBounds = {
  createWaitMs: 150,
  getDeadlineMs: 200,
  initialDelayMs: 20,
  backoffFactor: 1.5,
  maxDelayMs: 60,
  jitterRatio: 0,
  maxConsecutiveTransientErrors: 3,
  maxSilenceMs: 10_000,
  maxMonitorMs: 60_000,
  approvalTimeoutMs: 1_000,
};

const directories: string[] = [];
const sessions: AgentSession[] = [];
afterEach(async () => {
  for (const session of sessions.splice(0)) session.dispose();
  await Promise.all(directories.splice(0).map((directory) => rm(directory, { recursive: true, force: true })));
});

function uiContext(confirm: (title: string, message: string) => Promise<boolean>, confirms: string[]): ExtensionUIContext {
  const noop = () => {};
  return {
    select: async () => undefined,
    confirm: async (title, message) => {
      confirms.push(message);
      return confirm(title, message);
    },
    input: async () => undefined,
    editor: async () => undefined,
    notify: noop,
    onTerminalInput: () => noop,
    setStatus: noop,
    setWorkingMessage: noop,
    setWorkingVisible: noop,
    setWorkingIndicator: noop,
    setHiddenThinkingLabel: noop,
    setWidget: noop,
    setFooter: noop,
    setHeader: noop,
    setTitle: noop,
    custom: async () => undefined,
    pasteToEditor: noop,
    setEditorText: noop,
    getEditorText: () => "",
  } as unknown as ExtensionUIContext;
