type Step = Parameters<ReturnType<typeof fauxProvider>["setResponses"]>[0][number];

const proposeCall = () =>
  fauxAssistantMessage(fauxToolCall("exa_proto_research", { action: "propose", topic: "Laya versus Jev" }), {
